// One registry is shared by the room service and the client. No room fills seats with bots.
export const nativeDuels=new Set(['ampe','oware','dame','ludo']);
const live={abedemu:[3,6,'Pass around one human defender'],football:[2,12,'Team football'],fourcorners:[4,4,'Four human defenders'],penalties:[2,2,'Shooter and goalkeeper'],onepole:[2,2,'Alternating shots'],laski:[3,5,'Human keeper and outfield players'],sulia:[2,5,'Nutmeg and chase'],stay:[3,8,'Hit, catch and change thrower'],chaskele:[2,2,'Batter and thrower'],pampanaa:[2,6,'Neighbourhood elimination'],pilolo:[2,3,'Shared neighbourhood search'],antoakyire:[3,9,'Cloth carrier and chaser'],sansankroma:[2,2,'Runner and hawk'],police:[2,2,'Rescuer and police'],counters:[2,2,'Shared floor match'],rubberband:[2,2,'Alternating bands'],alasa:[2,2,'Alternating seeds'],chempe:[2,2,'Human call and response'],pempenaa:[2,4,'Shared counting circle'],mbobagor:[2,6,'Shared passing circle'],kyekyekule:[2,2,'Human leader and follower']};
export function multiplayerGame(id){if(nativeDuels.has(id))return{min:2,max:2,type:'duel',label:'Live head-to-head'};if(live[id]){const [min,max,label]=live[id];return{min,max,type:'live',label};}return{min:2,max:8,type:'turns',label:'Shared arena · human turns'};}
export function roomSettings(game,count){return{jumpPlayers:1,jumpOpponents:'local',jumpBar:false,abedemuCount:game==='abedemu'?count:6,color:0xc05336,opponent:'local',difficulty:'normal',balance:0,teamSize:game==='football'?Math.max(1,Math.floor((count-(count>=4?2:0))/2)):3,goalSize:game==='football'&&count<4?'small':'big',goalStyle:'net',poleStyle:'sticks',counterCount:3,cornersLives:3,cornersTouch:'normal',pitchSurface:'auto',penaltyControl:'aim'};}
export function seeded(seed,fn){const original=Math.random;let state=seed>>>0;Math.random=()=>{state+=0x6D2B79F5;let t=state;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};try{return fn();}finally{Math.random=original;}}
export function validateInput(msg){const value=msg.input||{},finite=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;if(!finite(value.x,-1,1)||!finite(value.z,-1,1))throw Error('Invalid movement');if(value.action!==undefined&&(typeof value.action!=='string'||!/^[-a-zA-Z0-9_]{1,32}$/.test(value.action)))throw Error('Invalid action');if(value.power!==undefined&&!finite(value.power,0,1.3))throw Error('Invalid power');if(value.point&&!['x','y','z'].every(k=>finite(value.point[k],-200,200)))throw Error('Invalid target');if(value.heading!==undefined&&!finite(value.heading,-1000,1000))throw Error('Invalid view');return{...(value.heading!==undefined?{heading:value.heading}:{}),x:value.x,z:value.z,sprint:!!value.sprint,...(value.action?{action:value.action,power:value.power??.4}:{}),...(value.point?{point:value.point}:{}),...(Number.isInteger(value.pick)&&value.pick>=0&&value.pick<100?{pick:value.pick}:{})};}
